package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public final class SourceActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private Button refresh;private TvBoxConfig config;private String lastReport;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout shell=TvUi.root(this);ScrollView scroll=new ScrollView(this);LinearLayout root=TvUi.col(this);scroll.addView(root);shell.addView(scroll);root.addView(TvUi.text(this,"TVBox 配置与网络源",28,TvUi.INK));TvUi.gap(this,root,14);SourceRepository repo=new SourceRepository(this);lastReport=repo.report();status=TvUi.text(this,lastReport,17,TvUi.ACCENT);root.addView(status);try{config=repo.load();}catch(Exception e){config=new TvBoxConfig();status.setText(e.getMessage());}
 root.addView(TvUi.text(this,"标准 API 可在网络影视中搜索。直播列表需更新后进入直播栏目。Spider/JAR、解析插件、代理地址、请求头定制与 EPG 暂未支持。",16,TvUi.MUTED));Button importButton=TvUi.button(this,"导入或更换配置");root.addView(importButton);importButton.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));Button search=TvUi.button(this,"搜索网络影视");root.addView(search);search.setOnClickListener(v->startActivity(new Intent(this,FilmSearchActivity.class)));
 refresh=TvUi.button(this,"更新配置中的直播列表（"+config.liveUrls.size()+"）");root.addView(refresh);refresh.setEnabled(!config.liveUrls.isEmpty());refresh.setOnClickListener(v->refresh());for(TvBoxConfig.Site site:config.sites){TvUi.gap(this,root,8);root.addView(TvUi.text(this,site.name+" · 标准 API",17,TvUi.INK));}Button clear=TvUi.button(this,"清除 TVBox 网络源配置");root.addView(clear);clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("清除网络源配置？").setMessage("已导入的直接媒体目录、收藏与历史保留。").setNegativeButton("取消",null).setPositiveButton("清除",(d,n)->{repo.clear();finish();}).show());Button back=TvUi.button(this,"返回");root.addView(back);back.setOnClickListener(v->finish());
 }
 @Override protected void onResume(){super.onResume();if(lastReport!=null&&!lastReport.equals(new SourceRepository(this).report()))recreate();}
 private void refresh(){refresh.setEnabled(false);status.setText("正在更新直播列表…");List<String> urls=new ArrayList<>(config.liveUrls);worker.execute(()->{ExecutorService requests=Executors.newFixedThreadPool(3);List<Callable<String>> tasks=new ArrayList<>();for(String url:urls)tasks.add(()->{String text=PublicHttp.get(url);String json=PlaylistImporter.convert(text,"domestic","未分类");return json;});int success=0,added=0,failed=0;try{List<Future<String>> results=requests.invokeAll(tasks,20,TimeUnit.SECONDS);for(Future<String> result:results)try{if(result.isCancelled()){failed++;continue;}added+=new CatalogRepository(this).merge(result.get(),"domestic","未分类");success++;}catch(Exception e){failed++;}}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{requests.shutdownNow();}String message="直播列表完成：成功 "+success+"，失败/超时 "+failed+"，读取 "+added+" 项（未进行播放验证）";runOnUiThread(()->{if(!isDestroyed()){status.setText(message);refresh.setEnabled(true);}});});}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
